function g3OfftableDivisionParts(divisor,stage){
 const d=Math.max(2,Number(divisor)||2),maxTens=stage===0?9:stage===1?9:9,candidates=[];
 for(let tens=10;tens<=90;tens+=10){if(tens%d!==0)continue;for(let ones=d;ones<=9;ones+=d){const dividend=tens+ones;if(dividend<=100)candidates.push({tens,ones,dividend,divisor:d,quotient:dividend/d})}}
 if(!candidates.length)return null;return candidates[ri(0,candidates.length-1)];
}
function g3RoundNumberQuestionData(stage){
 const d=Math.max(0,Math.min(2,Number(stage)||0));
 const types=d===0?["tMul","tDiv","hAdd","hSub"]:d===1?["tMul","tDiv","hMul","hDiv","tAdd","tSub","hAdd","hSub"]:["tMul","tDiv","hMul","hDiv","tAdd","tSub","hAdd","hSub","chainAdd","chainMul"];
 const type=types[ri(0,types.length-1)];let text,answer,ex,audit={type:"roundNumbers",variant:type};
 if(type==="tMul"){const units=ri(2,9),k=ri(2,5),a=units*10;answer=a*k;text=`<b>${a} · ${k}</b> = ?`;ex=`${units} дес. · ${k} = ${units*k} дес. = <b>${answer}</b>.`;audit={...audit,a,k,answer}}
 else if(type==="tDiv"){const k=ri(2,5),q=ri(1,Math.floor(9/k)||1)*10,a=q*k;answer=q;text=`<b>${a} : ${k}</b> = ?`;ex=`${a/10} дес. : ${k} = ${answer/10} дес. = <b>${answer}</b>.`;audit={...audit,a,k,answer}}
 else if(type==="hMul"){const units=ri(1,Math.floor(9/2)),k=ri(2,Math.min(4,Math.floor(9/units)||2)),a=units*100;answer=a*k;text=`<b>${a} · ${k}</b> = ?`;ex=`${units} сот. · ${k} = ${units*k} сот. = <b>${answer}</b>.`;audit={...audit,a,k,answer}}
 else if(type==="hDiv"){const k=ri(2,4),q=ri(1,Math.floor(9/k)||1)*100,a=q*k;answer=q;text=`<b>${a} : ${k}</b> = ?`;ex=`${a/100} сот. : ${k} = ${answer/100} сот. = <b>${answer}</b>.`;audit={...audit,a,k,answer}}
 else if(type==="tAdd"){const a=ri(1,7)*10,b=ri(1,9-Math.floor(a/10))*10;answer=a+b;text=`<b>${a} + ${b}</b> = ?`;ex=`${a/10} дес. + ${b/10} дес. = ${(a+b)/10} дес. = <b>${answer}</b>.`;audit={...audit,a,b,answer}}
 else if(type==="tSub"){const a=ri(3,9)*10,b=ri(1,Math.floor(a/10)-1)*10;answer=a-b;text=`<b>${a} − ${b}</b> = ?`;ex=`${a/10} дес. − ${b/10} дес. = ${(a-b)/10} дес. = <b>${answer}</b>.`;audit={...audit,a,b,answer}}
 else if(type==="hAdd"){const au=ri(1,7),bu=ri(1,9-au),a=au*100,b=bu*100;answer=a+b;text=`<b>${a} + ${b}</b> = ?`;ex=`${au} сот. + ${bu} сот. = ${au+bu} сот. = <b>${answer}</b>.`;audit={...audit,a,b,answer}}
 else if(type==="hSub"){const au=ri(3,9),bu=ri(1,au-1),a=au*100,b=bu*100;answer=a-b;text=`<b>${a} − ${b}</b> = ?`;ex=`${au} сот. − ${bu} сот. = ${au-bu} сот. = <b>${answer}</b>.`;audit={...audit,a,b,answer}}
 else if(type==="chainAdd"){const a=ri(2,6)*100,b=ri(1,Math.max(1,8-a/100))*100,c=ri(1,Math.min(3,(a+b)/100-1))*100;answer=a+b-c;text=`<b>${a} + ${b} − ${c}</b> = ?`;ex=`Сначала ${a} + ${b} = ${a+b}.<br>Потом ${a+b} − ${c} = <b>${answer}</b>.`;audit={...audit,a,b,c,answer}}
 else {const a=ri(2,4)*10,k=ri(2,Math.floor(9/(a/10))),c=ri(1,9)*10;answer=a*k+c;text=`<b>${a} · ${k} + ${c}</b> = ?`;ex=`Сначала ${a} · ${k} = ${a*k}.<br>Потом ${a*k} + ${c} = <b>${answer}</b>.`;audit={...audit,a,k,c,answer}}
 return {text,answer,ex,audit};
}
