 if(swap.length>2){const i=ri(0,swap.length-2),t=swap[i];swap[i]=swap[i+1];swap[i+1]=t}rotate.push(rotate.shift());
 const label=a=>a.join(", "),text=`Расположите числа <b>${values.join(", ")}</b> ${ascending?"по возрастанию":"по убыванию"}.`;
 return g6ChoiceQuestion(text,label(correct),[label(rev),label(swap),label(rotate)],`${ascending?"По возрастанию":"По убыванию"}: <b>${label(correct)}</b>.`,sig,{type:"g3Order",values:values.slice(),ascending,answer:correct.slice()});
}
